import java.util.concurrent.ConcurrentHashMap;
import java.util.Optional;

public class ConnectionRegistry {

    // A tiny immutable record of exactly where one user's live socket lives.
    public static class Connection {
        public final String gatewayId;
        public final String socketId;
        public final long lastHeartbeatMillis;

        public Connection(String gatewayId, String socketId, long lastHeartbeatMillis) {
            this.gatewayId = gatewayId;
            this.socketId = socketId;
            this.lastHeartbeatMillis = lastHeartbeatMillis;
        }
    }

    // In production this map is a sharded, replicated Redis cluster, not a
    // single JVM's memory, but the semantics it exposes are exactly this.
    private final ConcurrentHashMap<String, Connection> userToConnection = new ConcurrentHashMap<>();

    public void register(String userId, String gatewayId, String socketId) {
        userToConnection.put(userId, new Connection(gatewayId, socketId, System.currentTimeMillis()));
    }

    public void heartbeat(String userId) {
        Connection existing = userToConnection.get(userId);
        if (existing != null) {
            userToConnection.put(userId, new Connection(existing.gatewayId, existing.socketId, System.currentTimeMillis()));
        }
    }

    public void deregister(String userId) {
        userToConnection.remove(userId);
    }

    // A user only counts as online if a heartbeat has been seen recently,
    // which is what lets a crashed gateway's stale entries self-expire.
    public Optional<Connection> lookup(String userId, long staleAfterMillis) {
        Connection connection = userToConnection.get(userId);
        if (connection == null) return Optional.empty();
        boolean isStale = System.currentTimeMillis() - connection.lastHeartbeatMillis > staleAfterMillis;
        return isStale ? Optional.empty() : Optional.of(connection);
    }

    public static void main(String[] args) {
        ConnectionRegistry registry = new ConnectionRegistry();
        registry.register("bob_42", "gateway-A", "socket-8842");

        Optional<Connection> found = registry.lookup("bob_42", 30_000);
        System.out.println("Bob is on: " + (found.isPresent() ? found.get().gatewayId : "offline"));

        Optional<Connection> unknown = registry.lookup("carol_7", 30_000);
        System.out.println("Carol is on: " + (unknown.isPresent() ? unknown.get().gatewayId : "offline"));
    }
}

