// A tiny immutable record of exactly where one user's live socket lives.
struct Connection {
    string gatewayId;
    string socketId;
    long long lastHeartbeatMillis;
};

class ConnectionRegistry {
public:
    void registerConnection(const string& userId, const string& gatewayId, const string& socketId) {
        lock_guard<mutex> guard(mtx);
        userToConnection[userId] = Connection{gatewayId, socketId, nowMillis()};
    }

    void heartbeat(const string& userId) {
        lock_guard<mutex> guard(mtx);
        auto it = userToConnection.find(userId);
        if (it != userToConnection.end()) {
            it->second.lastHeartbeatMillis = nowMillis();
        }
    }

    void deregister(const string& userId) {
        lock_guard<mutex> guard(mtx);
        userToConnection.erase(userId);
    }

    // A user only counts as online if a heartbeat has been seen recently,
    // which is what lets a crashed gateway's stale entries self-expire.
    optional<Connection> lookup(const string& userId, long long staleAfterMillis) {
        lock_guard<mutex> guard(mtx);
        auto it = userToConnection.find(userId);
        if (it == userToConnection.end()) return nullopt;
        bool isStale = (nowMillis() - it->second.lastHeartbeatMillis) > staleAfterMillis;
        return isStale ? nullopt : optional<Connection>(it->second);
    }

private:
    unordered_map<string, Connection> userToConnection;
    mutex mtx;

    static long long nowMillis() {
        return chrono::duration_cast<chrono::milliseconds>(
            chrono::system_clock::now().time_since_epoch()).count();
    }
};

int main() {
    ConnectionRegistry registry;
    registry.registerConnection("bob_42", "gateway-A", "socket-8842");

    auto found = registry.lookup("bob_42", 30000);
    cout << "Bob is on: " << (found.has_value() ? found->gatewayId : "offline") << endl;

    auto unknown = registry.lookup("carol_7", 30000);
    cout << "Carol is on: " << (unknown.has_value() ? unknown->gatewayId : "offline") << endl;
    return 0;
}

