import java.util.Optional;

public class PresenceService {

    private static final long STALE_AFTER_MILLIS = 30_000;

    private final ConnectionRegistry connectionRegistry;

    public PresenceService(ConnectionRegistry connectionRegistry) {
        this.connectionRegistry = connectionRegistry;
    }

    public boolean isOnline(String userId) {
        return connectionRegistry.lookup(userId, STALE_AFTER_MILLIS).isPresent();
    }

    // Returns the specific gateway holding this user's connection, or empty
    // if they are offline, which callers treat as "route to the offline path".
    public Optional<String> gatewayFor(String userId) {
        return connectionRegistry.lookup(userId, STALE_AFTER_MILLIS)
            .map(connection -> connection.gatewayId);
    }

    public static void main(String[] args) {
        ConnectionRegistry registry = new ConnectionRegistry();
        registry.register("bob_42", "gateway-A", "socket-8842");
        PresenceService presenceService = new PresenceService(registry);

        System.out.println("Bob online: " + presenceService.isOnline("bob_42"));
        System.out.println("Bob's gateway: " + presenceService.gatewayFor("bob_42").orElse("none"));
        System.out.println("Carol online: " + presenceService.isOnline("carol_7"));
    }
}

