import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

public class OfflineMessageQueue {

    public static class QueuedMessage {
        public final String messageId;
        public final String chatId;
        public final String ciphertext;

        public QueuedMessage(String messageId, String chatId, String ciphertext) {
            this.messageId = messageId;
            this.chatId = chatId;
            this.ciphertext = ciphertext;
        }
    }

    // In production this is a durable, per-user partition in a wide-column
    // store, not an in-memory list, but the enqueue/drain contract is the same.
    private final ConcurrentHashMap<String, List<QueuedMessage>> queuesByUser = new ConcurrentHashMap<>();

    public void enqueue(String userId, QueuedMessage message) {
        queuesByUser.computeIfAbsent(userId, k -> Collections.synchronizedList(new ArrayList<>())).add(message);
    }

    // Drains and clears the queue atomically, so a message is never handed
    // out twice even if drain is called again before delivery finishes.
    public List<QueuedMessage> drain(String userId) {
        List<QueuedMessage> pending = queuesByUser.remove(userId);
        return pending == null ? Collections.emptyList() : pending;
    }

    public static void main(String[] args) {
        OfflineMessageQueue queue = new OfflineMessageQueue();
        queue.enqueue("bob_42", new QueuedMessage("m1", "chat_alice_bob", "<ciphertext>"));
        queue.enqueue("bob_42", new QueuedMessage("m2", "chat_alice_bob", "<ciphertext>"));

        List<QueuedMessage> drained = queue.drain("bob_42");
        System.out.println("Delivered on reconnect: " + drained.size() + " messages");

        List<QueuedMessage> drainedAgain = queue.drain("bob_42");
        System.out.println("Second drain finds: " + drainedAgain.size() + " messages");
    }
}

