class OfflineMessageQueue {
public:
    void enqueue(const string& userId, const QueuedMessage& message) {
        lock_guard<mutex> guard(mtx);
        queuesByUser[userId].push_back(message);
    }

    // Drains and clears the queue atomically, so a message is never handed
    // out twice even if drain is called again before delivery finishes.
    vector<QueuedMessage> drain(const string& userId) {
        lock_guard<mutex> guard(mtx);
        auto it = queuesByUser.find(userId);
        if (it == queuesByUser.end()) return {};
        vector<QueuedMessage> pending = std::move(it->second);
        queuesByUser.erase(it);
        return pending;
    }

private:
    unordered_map<string, vector<QueuedMessage>> queuesByUser;
    mutex mtx;
};

