import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

public class MessageDeliveryService {

    public enum State { SENT, DELIVERED, READ }

    public static class Message {
        public final String messageId;
        public final String chatId;
        public final String senderId;
        public final String recipientId;
        public final String ciphertext;
        public State state;

        public Message(String messageId, String chatId, String senderId, String recipientId, String ciphertext) {
            this.messageId = messageId;
            this.chatId = chatId;
            this.senderId = senderId;
            this.recipientId = recipientId;
            this.ciphertext = ciphertext;
            this.state = State.SENT;
        }
    }

    private final PresenceService presenceService;
    private final OfflineMessageQueue offlineQueue;

    // Dedup index: clientMessageId -> messageId already persisted for it.
    // This is what makes retrying a send safe, exactly as walked through
    // in Section 13.2.
    private final ConcurrentHashMap<String, String> seenClientMessageIds = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, Message> messageStore = new ConcurrentHashMap<>();
    private int nextMessageId = 1;

    public MessageDeliveryService(PresenceService presenceService, OfflineMessageQueue offlineQueue) {
        this.presenceService = presenceService;
        this.offlineQueue = offlineQueue;
    }

    // Returns the persisted message. Safe to call twice with the same
    // clientMessageId, the second call returns the original without
    // creating a duplicate or re-triggering delivery side effects.
    public synchronized Message send(String clientMessageId, String chatId, String senderId,
                                      String recipientId, String ciphertext) {
        String existingMessageId = seenClientMessageIds.get(clientMessageId);
        if (existingMessageId != null) {
            return messageStore.get(existingMessageId);
        }

        String messageId = "m" + (nextMessageId++);
        Message message = new Message(messageId, chatId, senderId, recipientId, ciphertext);
        messageStore.put(messageId, message);
        seenClientMessageIds.put(clientMessageId, messageId);

        route(message, recipientId);
        return message;
    }

    private void route(Message message, String recipientId) {
        Optional<String> gateway = presenceService.gatewayFor(recipientId);
        if (gateway.isPresent()) {
            deliverLive(message, gateway.get());
        } else {
            offlineQueue.enqueue(recipientId,
                new OfflineMessageQueue.QueuedMessage(message.messageId, message.chatId, message.ciphertext));
            triggerPushNotification(recipientId);
        }
    }

    private void deliverLive(Message message, String gatewayId) {
        // In production this hops to the recipient's specific gateway over
        // an internal RPC, exactly as shown in the gateway message hop diagram.
        System.out.println("Delivering " + message.messageId + " live via " + gatewayId);
        message.state = State.DELIVERED;
    }

    private void triggerPushNotification(String recipientId) {
        System.out.println("Recipient " + recipientId + " offline, push notification queued");
    }

    public void markDelivered(String messageId) {
        Message message = messageStore.get(messageId);
        if (message != null) message.state = State.DELIVERED;
    }

    public void markRead(String messageId) {
        Message message = messageStore.get(messageId);
        if (message != null) message.state = State.READ;
    }

    public static void main(String[] args) {
        ConnectionRegistry registry = new ConnectionRegistry();
        PresenceService presenceService = new PresenceService(registry);
        OfflineMessageQueue offlineQueue = new OfflineMessageQueue();
        MessageDeliveryService deliveryService = new MessageDeliveryService(presenceService, offlineQueue);

        // Bob is offline: falls back to the offline queue plus a push notification.
        Message m1 = deliveryService.send("client-uuid-1", "chat_alice_bob", "alice_1", "bob_42", "<ciphertext>");
        System.out.println("First send state: " + m1.state);

        // Alice's client retries the exact same send after a lost ack.
        Message m1Retry = deliveryService.send("client-uuid-1", "chat_alice_bob", "alice_1", "bob_42", "<ciphertext>");
        System.out.println("Retry returns same messageId: " + (m1.messageId.equals(m1Retry.messageId)));

        // Bob reconnects, presence gets registered, a new send now delivers live.
        registry.register("bob_42", "gateway-A", "socket-8842");
        Message m2 = deliveryService.send("client-uuid-2", "chat_alice_bob", "alice_1", "bob_42", "<ciphertext>");
        System.out.println("Second send state: " + m2.state);
    }
}

