public class ReceiptStateMachine {

    public enum State { SENT, DELIVERED, READ }

    // Only forward transitions are legal: SENT -> DELIVERED -> READ.
    // Anything else, including a no-op transition to the same state, is rejected.
    public boolean canTransition(State from, State to) {
        if (from == State.SENT) return to == State.DELIVERED || to == State.READ;
        if (from == State.DELIVERED) return to == State.READ;
        return false; // READ is terminal, nothing legally follows it
    }

    public State transition(State current, State target) {
        if (!canTransition(current, target)) {
            throw new IllegalStateException("Cannot move from " + current + " to " + target);
        }
        return target;
    }

    public static void main(String[] args) {
        ReceiptStateMachine machine = new ReceiptStateMachine();

        State state = State.SENT;
        state = machine.transition(state, State.DELIVERED);
        System.out.println("After delivery: " + state);

        state = machine.transition(state, State.READ);
        System.out.println("After read: " + state);

        try {
            machine.transition(state, State.SENT);
        } catch (IllegalStateException e) {
            System.out.println("Rejected as expected: " + e.getMessage());
        }
    }
}

